return async function(config, ctx) {
  const uploadUrl = String(config.apiUrl || '').trim();
  const token = String(config.token || '').trim();
  if (!uploadUrl || !token) return { options: [] };

  let baseUrl = uploadUrl.replace(/\/$/, '');
  if (/\/api\/v2\/upload$/i.test(baseUrl)) {
    baseUrl = baseUrl.replace(/\/api\/v2\/upload$/i, '');
  }

  const res = await ctx.fetch(baseUrl + '/api/v2/group', {
    headers: {
      'Authorization': 'Bearer ' + token,
      'Accept': 'application/json, text/plain, */*'
    }
  });

  if (!res.ok) throw new Error('HTTP ' + res.status);
  const json = res.body;
  if (!json || (json.status !== true && json.status !== 'success')) {
    throw new Error((json && json.message) || '获取存储列表失败');
  }

  const storages = json.data && json.data.storages ? json.data.storages : [];
  return {
    options: storages.map(item => ({ label: item.name, value: String(item.id) }))
  };
}

