return async function (config, file, ctx) {
    if (!config.apiUrl) throw new Error('Missing apiUrl');
    const blob = await (await fetch(file.data)).blob();
    const fd = new FormData();
    fd.append('file', blob, file.name);
    if (config.storageId) fd.append('storage_id', String(config.storageId));
    if (config.albumId) fd.append('album_id', String(config.albumId));
    fd.append('is_public', config.isPublic === false ? '0' : '1');
    const headers = {
        'Accept': 'application/json, text/plain, */*'
    };
    if (config.token) headers['Authorization'] = 'Bearer ' + config.token;
    const res = await ctx.fetch(config.apiUrl, { method: 'POST', headers: headers, body: fd });
    const json = res.body; if (!res.ok) {
        const msg = (json && (json.message || json.msg)) || ('HTTP ' + res.status);
        throw new Error(msg);
    } const ok = json && (json.status === true || json.status === 'success' || json.success === true || json.code === 200);
    if (!ok) {
        throw new Error((json && (json.message || json.msg)) || 'Upload failed');

    } const data = (json && json.data) || {};
    const url = data.url || data.public_url || (data.links && (data.links.url || data.links.html || data.links.markdown));
    if (!url) throw new Error('Upload succeeded but no URL found in response');
    return url;
}
